    static void RoadCorners(Transform network,Vector2 node,TownRoadPlan plan,Material pavement,Material curb){var arms=RoadArms(node,plan);if(arms.Length<2)return;var centre=new Vector3(node.x,DeckY(node.x,node.y),node.y);var root=RoadGroup(network,"Intersection_"+node.x.ToString("0.0")+"_"+node.y.ToString("0.0"),centre);var g=new RoadGeometry();var k=new RoadGeometry();float h=plan.asphaltWidth/2,c=plan.curbWidth,w=plan.sidewalkWidth;foreach(float sx in new[]{-1f,1f})foreach(float sz in new[]{-1f,1f}){if(!arms.Contains(new Vector2(sx,0))||!arms.Contains(new Vector2(0,sz)))continue;Rect R(float x0,float z0,float x1,float z1)=>Rect.MinMaxRect(Mathf.Min(x0,x1),Mathf.Min(z0,z1),Mathf.Max(x0,x1),Mathf.Max(z0,z1));g.FlatRect(R(node.x+sx*(h+c),node.y+sz*(h+c),node.x+sx*(h+c+w),node.y+sz*(h+c+w)),(x,z)=>DeckY(x,z)+.18f);k.FlatRect(R(node.x+sx*h,node.y+sz*h,node.x+sx*(h+c),node.y+sz*(h+c+w)),(x,z)=>DeckY(x,z)+.2f);k.FlatRect(R(node.x+sx*h,node.y+sz*h,node.x+sx*(h+c+w),node.y+sz*(h+c)),(x,z)=>DeckY(x,z)+.2f);}RoadMesh(root,root.name+"_Pavement",g,pavement,true);RoadMesh(root,root.name+"_Curbs",k,curb,true);}
    static void RoadCrosswalks(Transform network,Vector2 node,TownRoadPlan plan,Material white){var arms=RoadArms(node,plan);if(arms.Length<2)return;var root=RoadGroup(network,"Crosswalks_"+node.x.ToString("0.0")+"_"+node.y.ToString("0.0"),new Vector3(node.x,DeckY(node.x,node.y),node.y));var g=new RoadGeometry();foreach(var arm in arms){
