    static void TurnPad(Transform network,RoadTurn turn,Material asphalt,Material sidewalk,Material curb,Material foundation){var root=RoadGroup(network,"Turnaround_"+turn.z,new Vector3(turn.x,DeckY(turn.x,turn.z),turn.z));var inner=new Rect(turn.x-5.4f,turn.z-5.4f,10.8f,10.8f);var road=new RoadGeometry();road.FlatRect(inner,DeckY);RoadMesh(root,root.name+"_Asphalt",road,asphalt,true);float half=turn.size/2;var p=new RoadGeometry();foreach(var rect in new[]{new Rect(turn.x-half,turn.z-half,turn.size,half-5.6f),new Rect(turn.x-half,turn.z+5.6f,turn.size,half-5.6f),new Rect(turn.x-half,turn.z-5.6f,half-5.6f,11.2f),new Rect(turn.x+5.6f,turn.z-5.6f,half-5.6f,11.2f)})p.FlatRect(rect,(x,z)=>DeckY(x,z)+.18f);RoadMesh(root,root.name+"_Walkway",p,sidewalk,true);var walls=new RoadGeometry();var corners=new[]{new Vector3(turn.x-half,0,turn.z-half),new Vector3(turn.x-half,0,turn.z+half),new Vector3(turn.x+half,0,turn.z+half),new Vector3(turn.x+half,0,turn.z-half)};for(int i=0;i<4;i++){var a=corners[i];var b=corners[(i+1)%4];a.y=DeckY(a.x,a.z)+.18f;b.y=DeckY(b.x,b.z)+.18f;walls.Wall(a,b,PlanningGround(roadLands,a.x,a.z)-.06f,PlanningGround(roadLands,b.x,b.z)-.06f);}RoadMesh(root,root.name+"_Foundation",walls,foundation,true);}
