    static void PowerPoles(Transform props,Material cable){const string path="Assets/SushiAndFish/ModularTown/StreetFurniture/SM_utility_pole_03_054adfaf5568.prefab";var posts=new List<Vector3>();foreach(float x in new[]{-36.6f,63.4f,107.4f}){var pair=new List<Vector3>();foreach(float z in new[]{-54f,-11f}){var p=new Vector3(x,0,z);var post=PlaceTownPrefab(path,props,"PowerPole_"+(++builtPoles),p,0,PropPavingY(x,z));pair.Add(new Vector3(x,post.transform.position.y+6.83f,z));}foreach(float offset in new[]{-.58f,0,.58f}){var a=pair[0]+Vector3.right*offset;var b=pair[1]+Vector3.right*offset;var root=RoadGroup(props,"PowerCable_"+builtPoles+"_"+offset,(a+b)/2);var g=new RoadGeometry();const int steps=24,sides=6;var rings=new List<Vector3[]>();for(int i=0;i<=steps;i++){float t=(float)i/steps;var p=Vector3.Lerp(a,b,t)-Vector3.up*(.65f*4*t*(1-t));rings.Add(Enumerable.Range(0,sides).Select(k=>p+new Vector3(Mathf.Cos(k*Mathf.PI*2/sides),Mathf.Sin(k*Mathf.PI*2/sides),0)*.024f).ToArray());}for(int i=0;i<steps;i++)for(int k=0;k<sides;k++)g.Quad(rings[i][k],rings[i+1][k],rings[i+1][(k+1)%sides],rings[i][(k+1)%sides]);RoadMesh(root,root.name,g,cable,false);}}}
